def index_groups(idx):
    """The contiguous runs of a sorted list of indices."""
    out, cur = [], [idx[0]]
    for a, b in zip(idx, idx[1:]):
        if b == a + 1: cur.append(b)
        else: out.append(cur); cur = [b]
